import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Python Strategy Hosting","description":"","frontmatter":{},"headers":[],"relativePath":"new-features/python-strategy-hosting.md","filePath":"new-features/python-strategy-hosting.md"}'),n={name:"new-features/python-strategy-hosting.md"};function i(s,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="python-strategy-hosting" tabindex="-1">Python Strategy Hosting <a class="header-anchor" href="#python-strategy-hosting" aria-label="Permalink to &quot;Python Strategy Hosting&quot;">​</a></h1><hr><h2 id="hosting-python-strategies-in-tradeboard" tabindex="-1">Hosting Python Strategies in Tradeboard <a class="header-anchor" href="#hosting-python-strategies-in-tradeboard" aria-label="Permalink to &quot;Hosting Python Strategies in Tradeboard&quot;">​</a></h2><p>Tradeboard hosts trusted Python trading strategies as separate subprocesses. Each run has its own process and log file, but lifecycle and scheduling state are still owned by the single Tradeboard web worker.</p><h3 id="_1-accessing-the-python-strategy-manager" tabindex="-1">1. Accessing the Python Strategy Manager <a class="header-anchor" href="#_1-accessing-the-python-strategy-manager" aria-label="Permalink to &quot;1. Accessing the Python Strategy Manager&quot;">​</a></h3><p>To begin, log into your Tradeboard dashboard:</p><ul><li>Click on your <strong>Profile</strong> icon in the top right corner.</li><li>Select <strong>Python Strategies</strong> from the dropdown menu.</li><li>This dashboard provides an overview of your total, running, and scheduled strategies.</li></ul><h3 id="_2-adding-a-new-strategy" tabindex="-1">2. Adding a New Strategy <a class="header-anchor" href="#_2-adding-a-new-strategy" aria-label="Permalink to &quot;2. Adding a New Strategy&quot;">​</a></h3><p>Click the <strong>Add Strategy</strong> button to open the configuration interface.</p><h4 id="uploading-the-script" tabindex="-1">Uploading the Script <a class="header-anchor" href="#uploading-the-script" aria-label="Permalink to &quot;Uploading the Script&quot;">​</a></h4><ul><li><strong>Strategy Name:</strong> Enter a unique descriptive name for your strategy.</li><li><strong>Python Script:</strong> Upload your <code>.py</code> file. Tradeboard supports standard Python libraries and the Tradeboard SDK.</li></ul><h4 id="configuration-scheduling" tabindex="-1">Configuration &amp; Scheduling <a class="header-anchor" href="#configuration-scheduling" aria-label="Permalink to &quot;Configuration &amp; Scheduling&quot;">​</a></h4><ul><li><strong>Exchange:</strong> Select the target exchange (e.g., NSE Equity, MCX Commodity, Crypto). Tradeboard is holiday-aware and will only run the strategy during valid market hours for the selected exchange.</li><li><strong>Schedule:</strong> Define the <strong>Start Time</strong>, <strong>Stop Time</strong>, and active days. Scheduling is required. Regular exchanges default to 09:00-16:00 IST on weekdays; crypto can run on all seven days.</li></ul><h3 id="_3-monitoring-management" tabindex="-1">3. Monitoring &amp; Management <a class="header-anchor" href="#_3-monitoring-management" aria-label="Permalink to &quot;3. Monitoring &amp; Management&quot;">​</a></h3><p>Once a strategy is added, it will appear on your Python Strategies page.</p><ul><li><strong>Start/Stop:</strong> Use the manual controls to trigger or halt the script execution.</li><li><strong>View Logs:</strong> Click &quot;View Logs&quot; to see real-time output. This section tracks data fetching, signal generation, and order execution. You can copy or download these logs for debugging.</li><li><strong>Edit Code:</strong> The built-in code editor allows for quick modifications directly within the browser, though it is recommended to test major changes locally first.</li></ul><h3 id="_4-execution-modes" tabindex="-1">4. Execution Modes <a class="header-anchor" href="#_4-execution-modes" aria-label="Permalink to &quot;4. Execution Modes&quot;">​</a></h3><p>Tradeboard features a toggle to prevent accidental trades during development:</p><ul><li><strong>Analyzer Mode:</strong> Use this for testing purposes. It allows the script to run and generate logs without sending real orders to the broker.</li><li><strong>Live Mode:</strong> Once your strategy is verified, switch to Live Mode to enable actual order placement.</li></ul><h3 id="_5-technical-environment-variables" tabindex="-1">5. Technical Environment Variables <a class="header-anchor" href="#_5-technical-environment-variables" aria-label="Permalink to &quot;5. Technical Environment Variables&quot;">​</a></h3><p>When your script runs within Tradeboard, several environment variables are automatically injected. You should use these instead of hardcoding sensitive data:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>TRADEBOARD_API_KEY</code></td><td>Decrypted application API key, when one is configured.</td></tr><tr><td><code>STRATEGY_ID</code></td><td>Unique identifier for the strategy.</td></tr><tr><td><code>STRATEGY_NAME</code></td><td>Strategy display name.</td></tr><tr><td><code>TRADEBOARD_HOST</code></td><td>Internal host URL for REST requests.</td></tr><tr><td><code>TRADEBOARD_STRATEGY_EXCHANGE</code></td><td>Exchange selected in the strategy schedule.</td></tr></tbody></table><p>Do not use the obsolete <code>TRADEBOARD_APIKEY</code> spelling. Build the WebSocket URL from the deployment configuration or your own strategy setting; <code>TRADEBOARD_WS_URL</code> is not one of the values injected by the current process launcher.</p><h3 id="_6-verifying-orders" tabindex="-1">6. Verifying Orders <a class="header-anchor" href="#_6-verifying-orders" aria-label="Permalink to &quot;6. Verifying Orders&quot;">​</a></h3><p>After a trade is triggered by your Python strategy, you can verify it in two places:</p><ol><li><strong>Strategy Logs:</strong> Shows the logic and parameters that triggered the trade.</li><li><strong>Order Book:</strong> Shows the status (Complete, Rejected, etc.) and details (Price, Quantity, Product Type) of the order sent to the broker.</li></ol><hr><h4 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h4><ul><li>Always test new strategies in <strong>Analyzer Mode</strong> for at least one full trading session.</li><li>Use the <strong>Python Strategy Guide</strong> link within the app for updated code snippets and recommended patterns.</li><li>Ensure your Tradeboard instance has a stable internet connection if running on a local machine to prevent WebSocket disconnections.</li><li>Run only code you trust. Hosted scripts execute as the Tradeboard operating-system user and inherit the application environment.</li><li>Keep one Gunicorn web worker. Strategy ownership, schedules, and live process state are process-local.</li><li>One open live-log page uses one long-lived server execution slot. Size an experimental gthread deployment for the expected number of simultaneous <code>/python</code> tabs and other streams.</li><li>Current main still has known threaded-shutdown risks around Unix <code>preexec_fn</code> and forced process-tree cleanup. Do not interpret process isolation as a guarantee of unattended 24x7 lifecycle recovery; after an abnormal server stop, verify that no old strategy process remains.</li></ul><p>The production default remains Gunicorn with one eventlet worker. The <a href="./../getting-started/gthread-migration.html">gthread migration</a> is opt-in and experimental until it is merged into the application main branch.</p>',30)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
